'use strict';

function moveViewport(currentIndex, command, itemCount) {
  if (!Number.isSafeInteger(itemCount) || itemCount <= 0) {
    throw new RangeError('itemCount must be a positive safe integer');
  }
  if (!Number.isInteger(currentIndex) || currentIndex < 0 || currentIndex >= itemCount) {
    throw new RangeError('currentIndex is out of range');
  }

  if (command === 'forward') {
    return (currentIndex + 1) % itemCount;
  }
  if (command === 'backward') {
    return (currentIndex - 1) % itemCount;
  }

  if (command !== null && typeof command === 'object' && !Array.isArray(command)) {
    const keys = Reflect.ownKeys(command);
    const exactShape = keys.length === 2 && keys.includes('type') && keys.includes('index');
    if (!exactShape || command.type !== 'jump' || !Number.isInteger(command.index)) {
      throw new TypeError('malformed jump command');
    }
    if (command.index < 0 || command.index >= itemCount) {
      throw new RangeError('jump index is out of range');
    }
    return command.index;
  }

  throw new TypeError('unsupported command');
}

module.exports = { moveViewport };

