'use strict';

const assert = require('node:assert');
const api = require('./solution');

assert.deepStrictEqual(Reflect.ownKeys(api), ['moveViewport']);
const { moveViewport } = api;
assert.strictEqual(typeof moveViewport, 'function');

assert.strictEqual(moveViewport(0, 'forward', 1), 0);
assert.strictEqual(moveViewport(0, 'backward', 1), 0);
assert.strictEqual(moveViewport(0, 'forward', 3), 1);
assert.strictEqual(moveViewport(2, 'forward', 3), 0);
assert.strictEqual(moveViewport(2, 'backward', 3), 1);
assert.strictEqual(moveViewport(0, 'backward', 3), 2);

const jump = Object.freeze({ type: 'jump', index: 2 });
assert.strictEqual(moveViewport(0, jump, 3), 2);
assert.deepStrictEqual(jump, { type: 'jump', index: 2 });

for (const [index, count] of [[-1, 3], [3, 3], [1.5, 3], [0, 0], [0, -1], [0, 1.5], [0, Number.MAX_SAFE_INTEGER + 1], [0, Infinity]]) {
  assert.throws(() => moveViewport(index, 'forward', count), RangeError);
}

for (const command of [null, undefined, 'next', 1, [], {}, { type: 'jump' }, { index: 1 }, { type: 'other', index: 1 }, { type: 'jump', index: 1.5 }, { type: 'jump', index: '1' }, { type: 'jump', index: 1, extra: true }]) {
  assert.throws(() => moveViewport(0, command, 3), TypeError);
}
assert.throws(() => moveViewport(0, { type: 'jump', index: -1 }, 3), RangeError);
assert.throws(() => moveViewport(0, { type: 'jump', index: 3 }, 3), RangeError);

